# Define both sets of tags
filter_tags &lt;- c(
  "team_strength_filter",
  "league_hfa_filter",
  "result_filter"
)

predict_tags &lt;- c(
  "team_strength_predict",
  "league_hfa_predict",
  "result_predict"
)

# Load filter data
filter_data &lt;- load_estimates_data(filter_tags, base_repo_url)

# Load predict data
predict_data &lt;- load_estimates_data(predict_tags, base_repo_url)




