# Clean up filter data
filter_data &lt;- filter_data |&gt;
  purrr::map(
    \(x) {
      x |&gt;
        dplyr::rename_with(
          ~ stringr::str_remove(.x, "^filtered_")
        ) |&gt;
        mutate(type = "filter")
    }
  )


# Clean up predict data
predict_data &lt;- predict_data |&gt;
  purrr::map(
    \(x) {
      x |&gt;
        dplyr::rename_with(
          ~ stringr::str_remove(.x, "^predicted_")
        ) |&gt;
        mutate(type = "predict")
    }
  )
